WITH filtered_web_events AS (SELECT *, LOWER(page) AS page_lower FROM web_events WHERE session_id = 34), summary AS (SELECT QUARTER(event_time) AS event_quarter, session_id, SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END) AS checkout_count FROM filtered_web_events GROUP BY QUARTER(event_time), session_id) SELECT event_quarter, session_id, checkout_count FROM summary ORDER BY checkout_count DESC;
